<script setup>
import { Link, router } from '@inertiajs/vue3';
import { reactive, ref, computed } from 'vue';
import AdminLayout from '../../../Layouts/AdminLayout.vue';
import { formatBeijingDateTime } from '../../../utils/date-time.js';

const props=defineProps({articles:Object,search:String,status:String});
const filters=reactive({q:props.search||'',status:props.status||''});
const activeArticle=ref(null);const publishDialog=ref(false);
const requiredChecks=computed(()=>activeArticle.value?.publishChecks?.filter(check=>check.required)||[]);
const canPublish=computed(()=>requiredChecks.value.every(check=>check.passed));
function filter(){router.get('/admin/articles',filters,{preserveState:true,replace:true});}
function publish(item){if(item.status==='published'){router.post(`/admin/articles/${item.id}/unpublish`);return}activeArticle.value=item;publishDialog.value=true;}
function confirmPublish(){if(!activeArticle.value||!canPublish.value)return;router.post(`/admin/articles/${activeArticle.value.id}/publish`,{}, {onSuccess:()=>{publishDialog.value=false;activeArticle.value=null}})}
</script>
<template><AdminLayout title="精读文章" section="内容管理 / 精读文章" description="管理文章正文、解析、重点词汇、阅读理解题与发布状态。"><template #actions><Link class="btn" href="/admin/articles/create"><el-button type="primary">＋ 新建文章</el-button></Link></template>
  <section class="card"><form class="filter-bar" @submit.prevent="filter"><el-input v-model="filters.q" class="search" clearable placeholder="搜索中英文标题" @keyup.enter="filter"/><el-select v-model="filters.status"><el-option label="全部状态" value=""/><el-option label="草稿" value="draft"/><el-option label="已发布" value="published"/></el-select><el-button type="primary" native-type="submit">筛选</el-button><el-button v-if="filters.q||filters.status" text type="primary" @click="filters.q='';filters.status='';filter()">清空</el-button></form>
  <div v-if="!articles.data.length" class="empty-state"><strong>{{ filters.q||filters.status?'没有匹配的文章':'还没有文章' }}</strong><span>{{ filters.q||filters.status?'试试其他搜索词或状态':'从新建文章开始添加内容' }}</span></div>
  <div v-else class="table-wrap"><el-table :data="articles.data" stripe><el-table-column label="ID" width="80"><template #default="scope"><span class="badge-id">#{{scope.row.id}}</span></template></el-table-column><el-table-column label="文章标题" min-width="250"><template #default="scope"><div class="table-primary">{{scope.row.translation||scope.row.title}}</div><div v-if="scope.row.translation" class="table-secondary">{{scope.row.title}}</div></template></el-table-column><el-table-column prop="level" label="级别" width="110"><template #default="scope">{{scope.row.level||'—'}}</template></el-table-column><el-table-column label="状态" width="110"><template #default="scope"><el-tag :type="scope.row.status==='published'?'success':'info'" effect="light">{{scope.row.status==='published'?'已发布':'草稿'}}</el-tag></template></el-table-column><el-table-column label="最后更新" min-width="160"><template #default="scope">{{formatBeijingDateTime(scope.row.updated_at)||'—'}}</template></el-table-column><el-table-column label="操作" width="190" fixed="right"><template #default="scope"><div class="table-actions"><Link :href="`/admin/articles/${scope.row.id}/edit`"><el-button link type="primary">编辑</el-button></Link><el-button v-if="scope.row.status!=='published'" size="small" type="primary" @click="publish(scope.row)">发布检查</el-button><el-button v-else size="small" type="danger" plain @click="publish(scope.row)">下架</el-button></div></template></el-table-column></el-table></div>
  <div v-if="articles.data.length" class="table-footer"><span>共 {{ articles.total }} 篇</span><el-pagination background layout="prev, pager, next" :current-page="articles.current_page" :page-count="articles.last_page" @current-change="page=>router.get('/admin/articles',{...filters,page},{preserveState:true,replace:true})"/></div>
  </section>
  <el-dialog v-model="publishDialog" title="发布前检查" width="min(560px, 92vw)"><template v-if="activeArticle"><p class="helper">{{activeArticle.translation||activeArticle.title}}</p><div class="publish-check-list"><div v-for="check in activeArticle.publishChecks" :key="check.key" class="publish-check-row"><span class="publish-check-icon" :class="check.passed?'passed':check.required?'failed':'optional'">{{check.passed?'✓':check.required?'!':'·'}}</span><span class="publish-check-label">{{check.label}}<small v-if="check.detail">{{check.detail}}</small></span><el-tag size="small" :type="check.passed?'success':check.required?'danger':'info'" effect="plain">{{check.passed?'已完成':check.required?'必需':'建议'}}</el-tag></div></div><el-alert v-if="!canPublish" class="publish-alert" type="error" :closable="false" show-icon title="请先完成所有必需项，修正后再进行发布。"/><el-alert v-else class="publish-alert" type="success" :closable="false" show-icon title="必需内容齐全，可以发布；建议项可后续补充。"/></template><template #footer><el-button @click="publishDialog=false">取消</el-button><el-button type="primary" :disabled="!canPublish" @click="confirmPublish">确认发布</el-button></template></el-dialog>
</AdminLayout></template>
<style scoped>
.publish-check-list{display:grid;gap:10px;margin:18px 0}.publish-check-row{display:flex;align-items:center;gap:12px;padding:11px 12px;border:1px solid var(--border,#ebeef5);border-radius:10px}.publish-check-icon{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;font-weight:700}.publish-check-icon.passed{color:#198754;background:#e8f7ef}.publish-check-icon.failed{color:#c0392b;background:#fff0ed}.publish-check-icon.optional{color:#8c8c8c;background:#f3f4f6}.publish-check-label{flex:1;color:#303133}.publish-check-label small{display:block;margin-top:3px;color:#909399}.publish-alert{margin-top:14px}
</style>
